true_attribute(ProfileKey, attribute(ProfileKey, true)).

articles_36_to_40_performed(Attributes) :-
    article_36_to_40_keys(ProfileKeys),
    maplist(true_attribute, ProfileKeys, Attributes).

all_duties_performed(Attributes) :-
    article_36_to_40_keys(EarlierKeys),
    article_41_keys(ReportKeys),
    append(EarlierKeys, ReportKeys, ProfileKeys),
    maplist(true_attribute, ProfileKeys, Attributes).

with_value(Attributes, ProfileKey, NewValue, Updated) :-
    maplist(set_if_key(ProfileKey, NewValue), Attributes, Updated).

set_if_key(ProfileKey, NewValue, attribute(ElementKey, _), attribute(ElementKey, NewValue)) :-
    ElementKey == ProfileKey.
set_if_key(ProfileKey, _, attribute(ElementKey, OldValue), attribute(ElementKey, OldValue)) :-
    ElementKey \== ProfileKey.

